/* Muhasabbah FED LAMSPAK Sarjana v3.0 - static GitHub Pages application */
const D=window.LAMSPAK_DATA, MATRIX=D.matrix, TABLES=D.tables, META=D.meta;
const STORAGE_KEY='muhasabbah_lamspak_s1_v3';
const EVIDENCE_POINTS={'Belum ada':0,'Draft':.33,'Tersedia':.67,'Terverifikasi':1};
const ID_FIELDS=[['programStudi','Nama Program Studi'],['upps','Unit Pengelola Program Studi'],['perguruanTinggi','Perguruan Tinggi'],['tahunEvaluasi','Tahun Evaluasi'],['ketuaProdi','Ketua Program Studi'],['alamat','Alamat'],['website','Website'],['email','Email'],['skAkreditasi','Nomor SK Akreditasi Terakhir']];
const TEAM_FIELDS=[['ketuaTim','Ketua Tim FED'],['anggotaTim','Anggota Tim / unit terlibat'],['reviewer','Reviewer/Auditor Internal'],['tanggalReview','Tanggal Review']];
const $=q=>document.querySelector(q), $$=q=>[...document.querySelectorAll(q)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=v=>{if(v===null||v===undefined||String(v).trim()==='')return null;const n=Number(String(v).replace(/\./g,'').replace(',','.'));return Number.isFinite(n)?n:null};
const rawNum=v=>{if(v===null||v===undefined||String(v).trim()==='')return null;const n=Number(String(v).replace(',','.'));return Number.isFinite(n)?n:null};
const fmt=n=>n===null||n===undefined||Number.isNaN(Number(n))?'-':Number(n).toLocaleString('id-ID',{maximumFractionDigits:3});
const todayISO=()=>new Date().toISOString().slice(0,10);
function toast(s){const t=$('#toast');t.textContent=s;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),1800)}
function download(blob,name){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;document.body.appendChild(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove()},1000)}
function freshCriterion(){return{score:null,scoreSource:'manual',narrative:'',evidence:'',evidenceStatus:'Belum ada',evidenceOwner:'',verifiedDate:'',assessorNote:'',metrics:{},plan:{recommendation:'',pic:'',dueDate:'',target:'',status:'Belum dimulai'}}}
function fresh(){const criteria={};MATRIX.forEach(m=>criteria[m.no]=freshCriterion());return{version:3,identity:{},team:{},front:{ringkasan:'',catatanMetode:''},criteria,tables:{},updatedAt:null}}
let state=fresh();
try{const old=JSON.parse(localStorage.getItem(STORAGE_KEY)||'null');if(old){state={...fresh(),...old,criteria:{...fresh().criteria,...(old.criteria||{})}};MATRIX.forEach(m=>state.criteria[m.no]={...freshCriterion(),...(state.criteria[m.no]||{}),plan:{...freshCriterion().plan,...(state.criteria[m.no]?.plan||{})},metrics:{...(state.criteria[m.no]?.metrics||{})}})}}catch(e){}
function save(){state.updatedAt=new Date().toISOString();localStorage.setItem(STORAGE_KEY,JSON.stringify(state));$('#saveStatus').textContent='Tersimpan '+new Date().toLocaleTimeString('id-ID',{hour:'2-digit',minute:'2-digit'});}
function validScore(m,s){if(s===null||s==='')return null;const n=Number(s);if(!Number.isFinite(n))return null;return Math.max(m.scoreFloor||0,Math.min(2,n))}
function priority(m,x){const s=x.score===null?null:Number(x.score);if(m.syaratAkreditasi&&s===0)return'Kritis';if(m.syaratUnggul&&(s===null||s<2))return'Kritis';if(s===0)return'Tinggi';if(s===null&&m.weight===5)return'Tinggi';if(s!==null&&(2-s)*m.weight>=5)return'Tinggi';if(s===1)return'Sedang';if((EVIDENCE_POINTS[x.evidenceStatus]||0)<1)return'Rendah';return'Pemeliharaan'}
function scoreStats(){let weighted=0,weightedPossible=0,set=0,evidenceW=0,evidenceMax=0;const standards={};let unggulMet=0,unggulTotal=0,accredFail=0;MATRIX.forEach(m=>{const x=state.criteria[m.no],s=x.score===null?null:Number(x.score);const k=m.standard;standards[k]??={weighted:0,max:0,set:0,count:0,evidence:0,evidenceMax:0};standards[k].max+=2*m.weight;standards[k].count++;evidenceMax+=m.weight;standards[k].evidenceMax+=m.weight;evidenceW+=(EVIDENCE_POINTS[x.evidenceStatus]||0)*m.weight;standards[k].evidence+=(EVIDENCE_POINTS[x.evidenceStatus]||0)*m.weight;if(s!==null&&Number.isFinite(s)){weighted+=s*m.weight;weightedPossible+=2*m.weight;set++;standards[k].weighted+=s*m.weight;standards[k].set++}if(m.syaratUnggul){unggulTotal++;if(s===2)unggulMet++}if(m.syaratAkreditasi&&s===0)accredFail++});return{weighted,max:META.weightedMax,index:weighted/META.weightedMax*100,completion:set/META.indicatorCount*100,set,evidencePct:evidenceMax?evidenceW/evidenceMax*100:0,standards,unggulMet,unggulTotal,accredFail}}
function narrativeFor(m,x){const s=x.score===null?null:Number(x.score),ev=x.evidenceStatus||'Belum ada',base=s===2?m.score2:s===1?m.score1:s===0?m.score0:'belum ada skor yang ditetapkan';const metric=measurementResult(m,x);let p=s===null?`Indikator ${m.no} belum dapat disimpulkan karena skor evaluator belum ditetapkan.`:`Indikator ${m.no} dinilai pada skor ${fmt(s)} dengan bobot ${m.weight}; kontribusi berbobot ${fmt(s*m.weight)} dari maksimum ${2*m.weight}. Dasar rubrik yang dipilih: ${base}`;if(metric?.summary)p+=` Hasil pengukuran terstruktur: ${metric.summary}`;p+=` Status bukti saat ini: ${ev}.`;if(x.evidence)p+=` Bukti/lokasi yang dicatat: ${x.evidence}`;if(s!==null&&s<2)p+=` Kesenjangan menuju skor 2 adalah pemenuhan rubrik: ${m.score2}`;else if(s===2)p+=` Capaian perlu dipertahankan dengan bukti sahih yang mutakhir, konsisten, dan dapat ditelusuri.`;return p}
function recommendationFor(m,x){const s=x.score===null?null:Number(x.score),p=priority(m,x);if(s===null)return`Tetapkan skor setelah memverifikasi bukti terhadap tiga deskriptor rubrik. Lengkapi bukti utama, penanggung jawab, dan data tahun pengukuran.`;if(m.syaratAkreditasi&&s===0)return`Prioritas kritis: kondisi ini pada matriks dinyatakan tidak memenuhi syarat terakreditasi. Lakukan perbaikan substantif, validasi data, dan review pimpinan sebelum pengajuan.`;if(m.syaratUnggul&&s<2)return`Prioritas kritis untuk target Unggul: butir ini ditandai eksplisit sebagai SYARAT PERLU UNGGUL. Susun tindakan yang langsung menutup gap menuju deskriptor skor 2 dan verifikasi bukti sebelum pengajuan.`;if(s===0)return`Prioritas tinggi: kondisi masih berada pada deskriptor tidak memenuhi. Tetapkan akar masalah, tindakan korektif, target terukur, PIC, tenggat, dan bukti keluaran.`;if(s===1)return`Tingkatkan dari “memenuhi” ke “pelampauan” dengan memenuhi seluruh unsur pada deskriptor skor 2. Fokus pada bukti implementasi, konsistensi beberapa tahun, evaluasi, dan tindak lanjut sesuai bunyi rubrik.`;if((EVIDENCE_POINTS[x.evidenceStatus]||0)<1)return`Skor 2 telah dipilih, tetapi bukti belum terverifikasi. Lakukan pemeriksaan keaslian, keterlacakan, konsistensi antar-FED/tabel, serta pengesahan reviewer internal.`;return`Pertahankan capaian melalui monitoring berkala, pemutakhiran bukti, dan pencatatan tindak lanjut agar pelampauan tetap berkelanjutan.`}

