9:{fields:[['RIPK','RIPK', 'number','']],calc:v=>v.RIPK==null?null:{score:v.RIPK>=3.25?2:1,summary:`RIPK ${fmt(v.RIPK)}; ambang skor 2 = 3,25.`}},
