function measurementValues(m,x){const cfg=CALC[m.no];if(!cfg)return null;const v={};for(const f of cfg.fields){const raw=x.metrics?.[f[0]];v[f[0]]=rawNum(raw)}return v}
function measurementResult(m,x){const cfg=CALC[m.no];if(!cfg)return null;try{return cfg.calc(measurementValues(m,x))}catch(e){return null}}
function measurementBox(m,x){const cfg=CALC[m.no];if(!cfg)return'';const r=measurementResult(m,x);return`<div class="measure-box"><b>Kalkulator indikator (deterministik)</b><p class="muted" style="margin:3px 0 8px">Masukkan nilai yang telah diverifikasi. Hasil kalkulator adalah saran skor berdasarkan formula rubrik, bukan pengganti judgement evaluator.</p><div class="metric-grid">${cfg.fields.map(f=>`<label class="metric-field">${esc(f[1])}${f[3]?` <span class="muted">(${esc(f[3])})</span>`:''}<input type="number" step="any" data-metric="${m.no}" data-mkey="${f[0]}" value="${esc(x.metrics?.[f[0]]??'')}"></label>`).join('')}</div><div class="calc-result">${r?`Saran skor: <b>${r.score===null?'perlu telaah manual':fmt(r.score)}</b>. ${esc(r.summary||'')}${r.warning?`<br><span class="tag warn">Catatan</span> ${esc(r.warning)}`:''}${r.score!==null?` <button class="btn small" data-usecalc="${m.no}">Gunakan skor terukur</button>`:''}`:'Lengkapi semua input untuk menghitung.'}</div></div>`}
function renderHero(){const s=scoreStats();$('#heroScore').textContent=s.index.toFixed(2);$('#scoreRing').style.setProperty('--pct',Math.min(100,s.index));let status='Belum dinilai',note='Lengkapi penilaian dan bukti.';if(s.set){if(s.completion<100){status='Evaluasi belum lengkap';note=`${s.set}/73 indikator dinilai; ${s.unggulMet}/${s.unggulTotal} syarat perlu Unggul mencapai skor 2.`}else if(s.accredFail){status='Ada syarat minimum bermasalah';note='Terdapat butir yang pada matriks dinyatakan tidak memenuhi syarat terakreditasi.'}else if(s.unggulMet<s.unggulTotal){status='Syarat perlu Unggul belum lengkap';note=`${s.unggulMet}/${s.unggulTotal} butir syarat perlu Unggul mencapai skor 2.`}else{status='Syarat bertanda telah terpenuhi';note='Semua butir yang eksplisit ditandai “SYARAT PERLU UNGGUL” mencapai skor 2; keputusan resmi tetap memerlukan asesmen LAMSPAK.'}}$('#heroStatus').textContent=status;$('#heroNote').textContent=note;}
function renderDashboard(){const s=scoreStats();const actions=MATRIX.map(m=>({m,x:state.criteria[m.no],p:priority(m,state.criteria[m.no])})).filter(z=>z.p==='Kritis'||z.p==='Tinggi').slice(0,10);$('#dashboard').innerHTML=`<div class="panel"><div class="panel-head"><div><p class="kicker">Ikhtisar terpisah</p><h2>Dashboard Kesiapan Internal</h2></div><span class="tag ${s.unggulMet===s.unggulTotal&&s.set===73?'good':'warn'}">Syarat perlu Unggul ${s.unggulMet}/${s.unggulTotal}</span></div><div class="kpis"><div class="kpi"><b>${s.index.toFixed(2)}</b><span>Indeks skor berbobot /100</span></div><div class="kpi"><b>${fmt(s.weighted)}/${META.weightedMax}</b><span>Skor berbobot</span></div><div class="kpi"><b>${Math.round(s.completion)}%</b><span>Indikator dinilai</span></div><div class="kpi"><b>${s.evidencePct.toFixed(0)}%</b><span>Kematangan bukti berbobot</span></div><div class="kpi"><b>${actions.length}</b><span>Prioritas kritis/tinggi (10 teratas)</span></div></div></div><div class="panel"><h3>Capaian per Standar</h3><div class="standard-bars">${Object.entries(s.standards).map(([k,v])=>{const p=v.max?v.weighted/v.max*100:0;return`<div class="standard-bar"><span>${esc(k.replace(/^\d+\.\s*/,''))}</span><div class="track"><i style="width:${p}%"></i></div><b>${p.toFixed(0)}%</b></div>`}).join('')}</div></div><div class="panel"><h3>Prioritas utama</h3>${actions.length?actions.map(z=>`<div class="priority-row"><div class="crit-num">${z.m.no}</div><div><b>${esc(z.m.indicator)}</b><div class="crit-meta"><span class="tag ${z.p==='Kritis'?'critical':'warn'}">${z.p}</span>${z.m.syaratUnggul?'<span class="tag critical">Syarat perlu Unggul</span>':''}</div></div><div>Skor <b>${z.x.score??'-'}</b></div><div>${esc(recommendationFor(z.m,z.x))}</div><div>${esc(z.x.plan?.dueDate||'Belum ada tenggat')}</div><div>${esc(z.x.plan?.status||'Belum dimulai')}</div></div>`).join(''):'<p class="muted">Tidak ada prioritas kritis/tinggi yang teridentifikasi.</p>'}</div>`}
function scoreOptions(m,x){let h='<option value="">Belum dinilai</option>';const cur=Number(x.score);if(x.score!==''&&Number.isFinite(cur)&&![0,1,2].includes(cur))h+=`<option value="${cur}" selected>${fmt(cur)} - Skor terukur disesuaikan</option>`;for(const s of [2,1,0]){if(s<(m.scoreFloor||0))continue;h+=`<option value="${s}" ${cur===s?'selected':''}>${s} - ${s===2?'Pelampauan':s===1?'Memenuhi':'Tidak memenuhi'}</option>`}return h}
function criterionHTML(m){const x=state.criteria[m.no],p=priority(m,x),an=narrativeFor(m,x),rec=recommendationFor(m,x),tables=(m.relatedTables||[]).map(id=>`Tabel ${id}`).join(', ');return`<article class="criterion" id="crit-${m.no}"><div class="crit-head"><div class="crit-num">${m.no}</div><div><h3>${esc(m.indicator)}</h3><div class="crit-meta"><span class="tag">Bobot ${m.weight}</span>${m.standardOutput?'<span class="tag info">Standar luaran</span>':''}${m.scoreFloor===1?'<span class="tag info">Skor minimum rubrik 1</span>':''}${m.syaratUnggul?'<span class="tag critical">SYARAT PERLU UNGGUL</span>':''}${m.syaratAkreditasi?'<span class="tag critical">Syarat minimum terakreditasi</span>':''}<span class="tag ${p==='Kritis'?'critical':p==='Tinggi'?'warn':p==='Sedang'?'info':'good'}">Prioritas ${p}</span></div></div><div><select class="score-select" data-score="${m.no}">${scoreOptions(m,x)}</select></div></div><div class="crit-body"><div class="rubrics"><div class="rubric r2"><b>Skor 2 - Pelampauan</b>${esc(m.score2)}</div><div class="rubric r1"><b>Skor 1 - Memenuhi</b>${esc(m.score1)}</div><div class="rubric r0"><b>Skor 0 - Tidak memenuhi</b>${esc(m.score0)}</div></div><div class="source-note"><b>Sumber:</b> ${esc(m.sourceLabel)}${m.notes?`<br><b>Keterangan matriks:</b> ${esc(m.notes)}`:''}${tables?`<br><b>Tabel FED terkait:</b> ${esc(tables)}`:''}</div>${measurementBox(m,x)}<div class="crit-fields"><label class="field wide">Narasi hasil penilaian otomatis<div class="auto-narrative">${esc(an)}</div><button class="btn small" type="button" data-copyNarr="${m.no}">Salin ke narasi FED</button></label><label class="field wide">Narasi Evaluasi Diri (editable)<textarea data-crit="${m.no}" data-key="narrative" placeholder="Uraikan kondisi aktual → data/fakta → bukti sahih → analisis kesenjangan → tindak lanjut.">${esc(x.narrative)}</textarea></label><label class="field">Bukti sahih / tautan / lokasi berkas<textarea data-crit="${m.no}" data-key="evidence">${esc(x.evidence)}</textarea></label><label class="field">Status bukti<select data-crit="${m.no}" data-key="evidenceStatus">${Object.keys(EVIDENCE_POINTS).map(v=>`<option ${x.evidenceStatus===v?'selected':''}>${v}</option>`).join('')}</select></label><label class="field">Pemilik bukti<input data-crit="${m.no}" data-key="evidenceOwner" value="${esc(x.evidenceOwner)}"></label><label class="field">Tanggal verifikasi<input type="date" data-crit="${m.no}" data-key="verifiedDate" value="${esc(x.verifiedDate)}"></label><label class="field wide">Rekomendasi berbasis gap<div class="auto-narrative">${esc(rec)}</div></label><label class="field wide">Catatan auditor internal<textarea data-crit="${m.no}" data-key="assessorNote">${esc(x.assessorNote)}</textarea></label><div class="wide action-grid"><label class="field">Rencana tindakan<input data-plan="${m.no}" data-pkey="recommendation" value="${esc(x.plan.recommendation)}" placeholder="Tindakan spesifik"></label><label class="field">PIC<input data-plan="${m.no}" data-pkey="pic" value="${esc(x.plan.pic)}"></label><label class="field">Tenggat<input type="date" data-plan="${m.no}" data-pkey="dueDate" value="${esc(x.plan.dueDate)}"></label><label class="field">Indikator keberhasilan<input data-plan="${m.no}" data-pkey="target" value="${esc(x.plan.target)}" placeholder="Output/KPI terukur"></label><label class="field">Status<select data-plan="${m.no}" data-pkey="status">${['Belum dimulai','Berjalan','Tertunda','Selesai','Diverifikasi'].map(v=>`<option ${x.plan.status===v?'selected':''}>${v}</option>`).join('')}</select></label></div></div></div></article>`}
function renderAssessment(){const q=$('#critSearch').value.trim().toLowerCase(),f=$('#critFilter').value,groups={};MATRIX.forEach(m=>{const x=state.criteria[m.no],p=priority(m,x);let ok=!q||String(m.no).includes(q)||m.indicator.toLowerCase().includes(q)||m.standard.toLowerCase().includes(q);if(f==='unset')ok=ok&&x.score===null;else if(f==='gap')ok=ok&&(x.score===null||Number(x.score)<2);else if(f==='unggul')ok=ok&&m.syaratUnggul;else if(f==='critical')ok=ok&&(p==='Kritis'||p==='Tinggi');else if(['0','1','2'].includes(f))ok=ok&&Number(x.score)===Number(f);if(ok)(groups[m.standard]??=[]).push(m)});$('#assessmentList').innerHTML=Object.entries(groups).map(([std,items])=>`<details class="criterion-group" open><summary><span>${esc(std)}</span><span>${items.filter(m=>state.criteria[m.no].score!==null).length}/${items.length} dinilai</span></summary>${items.map(criterionHTML).join('')}</details>`).join('')||'<div class="panel">Tidak ada indikator sesuai filter.</div>';$('#assessmentCount').textContent=`${scoreStats().set}/73 dinilai`;bindAssessment()}
function bindAssessment(){$$('[data-score]').forEach(el=>el.onchange=()=>{const m=MATRIX.find(x=>x.no==el.dataset.score),x=state.criteria[m.no];x.score=el.value===''?null:validScore(m,Number(el.value));x.scoreSource='manual';save();renderAll(false)});$$('[data-crit]').forEach(el=>{const ev=el.tagName==='SELECT'||el.type==='date'?'change':'input';el.addEventListener(ev,()=>{state.criteria[el.dataset.crit][el.dataset.key]=el.value;save();if(el.dataset.key==='evidenceStatus'){renderHero();renderDashboard()}})});$$('[data-plan]').forEach(el=>{const ev=el.tagName==='SELECT'||el.type==='date'?'change':'input';el.addEventListener(ev,()=>{state.criteria[el.dataset.plan].plan[el.dataset.pkey]=el.value;save()})});$$('[data-metric]').forEach(el=>el.addEventListener('input',()=>{state.criteria[el.dataset.metric].metrics[el.dataset.mkey]=el.value;save()}));$$('[data-metric]').forEach(el=>el.addEventListener('change',()=>renderAssessment()));$$('[data-usecalc]').forEach(b=>b.onclick=()=>{const m=MATRIX.find(x=>x.no==b.dataset.usecalc),x=state.criteria[m.no],r=measurementResult(m,x);if(r&&r.score!==null){x.score=r.score;x.scoreSource='calculator';save();renderAll(false);toast('Skor terukur diterapkan ke butir '+m.no)}});$$('[data-copyNarr]').forEach(b=>b.onclick=()=>{const m=MATRIX.find(x=>x.no==b.dataset.copynarr),x=state.criteria[m.no];x.narrative=narrativeFor(m,x);save();renderAssessment();toast('Narasi disalin')})}
function renderPlans(){const list=MATRIX.map(m=>({m,x:state.criteria[m.no],p:priority(m,state.criteria[m.no])})).filter(z=>z.x.score===null||Number(z.x.score)<2||z.x.evidenceStatus!=='Terverifikasi'||z.x.plan.status!=='Diverifikasi').sort((a,b)=>{const o={Kritis:0,Tinggi:1,Sedang:2,Rendah:3,Pemeliharaan:4};return o[a.p]-o[b.p]||b.m.weight-a.m.weight||a.m.no-b.m.no});$('#planList').innerHTML=list.map(z=>`<div class="priority-row"><div class="crit-num">${z.m.no}</div><div><b>${esc(z.m.indicator)}</b><small class="muted">${esc(z.m.standard)}</small></div><span class="tag ${z.p==='Kritis'?'critical':z.p==='Tinggi'?'warn':z.p==='Sedang'?'info':'good'}">${z.p}</span><input data-planquick="${z.m.no}" data-pq="recommendation" value="${esc(z.x.plan.recommendation||recommendationFor(z.m,z.x))}"><input type="date" data-planquick="${z.m.no}" data-pq="dueDate" value="${esc(z.x.plan.dueDate)}"><select data-planquick="${z.m.no}" data-pq="status">${['Belum dimulai','Berjalan','Tertunda','Selesai','Diverifikasi'].map(v=>`<option ${z.x.plan.status===v?'selected':''}>${v}</option>`).join('')}</select></div>`).join('')||'<p>Semua rencana telah diverifikasi.</p>';$$('[data-planquick]').forEach(el=>{const ev=el.tagName==='SELECT'||el.type==='date'?'change':'input';el.addEventListener(ev,()=>{state.criteria[el.dataset.planquick].plan[el.dataset.pq]=el.value;save()})})}

/* 43 table engine */
function colName(c){let s='';for(c++;c>0;c=Math.floor((c-1)/26))s=String.fromCharCode(65+(c-1)%26)+s;return s}function addr(r,c){return colName(c)+(r+1)}function parseAddr(a){const m=/^([A-Z]+)(\d+)$/i.exec(a);if(!m)return null;let c=0;for(const ch of m[1].toUpperCase())c=c*26+ch.charCodeAt(0)-64;return[Number(m[2])-1,c-1]}
function tableOv(id){return state.tables[id]??={}}
function rawCell(t,a){const ov=tableOv(t.id);if(Object.prototype.hasOwnProperty.call(ov,a))return ov[a];const p=parseAddr(a);return p?t.values[p[0]]?.[p[1]]??'':''}
function rangeCells(spec){const [a,b]=spec.split(':');const p1=parseAddr(a),p2=parseAddr(b||a);if(!p1||!p2)return[];const out=[];for(let r=Math.min(p1[0],p2[0]);r<=Math.max(p1[0],p2[0]);r++)for(let c=Math.min(p1[1],p2[1]);c<=Math.max(p1[1],p2[1]);c++)out.push(addr(r,c));return out}
function splitArgs(s){const out=[];let d=0,start=0;for(let i=0;i<s.length;i++){if(s[i]==='(')d++;else if(s[i]===')')d--;else if(s[i]===','&&d===0){out.push(s.slice(start,i));start=i+1}}out.push(s.slice(start));return out}
function cellNumber(v){const n=rawNum(v);return n===null?0:n}
function evalTables(t){const computed={};const present=a=>Object.prototype.hasOwnProperty.call(computed,a)||String(rawCell(t,a)??'').trim()!=='';const get=a=>Object.prototype.hasOwnProperty.call(computed,a)?computed[a]:cellNumber(rawCell(t,a));const ev=formula=>{let e=String(formula).trim().replace(/^=/,'');const ifm=/^IF\((.*)\)$/i.exec(e);if(ifm){const a=splitArgs(ifm[1]);if(a.length===3)return ev(a[0])?ev(a[1]):ev(a[2])}e=e.replace(/(SUM|AVERAGE)\(([^()]*)\)/gi,(all,fn,inside)=>{const cells=[];splitArgs(inside).forEach(p=>rangeCells(p.trim()).forEach(a=>cells.push(a)));const vals=(fn.toUpperCase()==='AVERAGE'?cells.filter(present):cells).map(get);return fn.toUpperCase()==='AVERAGE'?(vals.length?vals.reduce((x,y)=>x+y,0)/vals.length:0):vals.reduce((x,y)=>x+y,0)});e=e.replace(/\b([A-Z]+\d+)\b/g,(m,a)=>String(get(a))).replace(/<>/g,'!=').replace(/(?<![<>!=])=(?!=)/g,'==');if(!/^[0-9eE+\-*/().<>=!\s]+$/.test(e))return 0;try{const v=Function('"use strict";return ('+e+')')();return Number.isFinite(Number(v))?Number(v):0}catch{return 0}};for(let p=0;p<6;p++)Object.entries(t.formulas).forEach(([a,f])=>computed[a]=ev(f));return computed}
function headerEnd(t){for(let r=2;r<Math.min(t.rows,10);r++){const nums=(t.values[r]||[]).filter(v=>typeof v==='number');if(nums.length>=2)return r}return Math.min(4,t.rows-1)}
function rowType(t,r){const row=t.values[r]||[],non=row.map((v,c)=>[v,c]).filter(([v])=>v!==null&&v!=='');if(r<=headerEnd(t))return'header';if(non.length===1&&typeof non[0][0]==='string'){const s=non[0][0].toLowerCase();if(/jumlah|keterangan|pendidikan|penelitian|pengabdian|semester|kelompok/.test(s))return'section'}return'data'}
function editable(t,r,c){const a=addr(r,c),base=t.values[r]?.[c];if(r<=headerEnd(t)||t.formulas[a])return false;if(base!==null&&base!=='')return false;return rowType(t,r)==='data'}
function tableCompletion(){let total=0,filled=0;TABLES.forEach(t=>{for(let r=t.renderStart;r<t.rows;r++)for(let c=0;c<t.cols;c++)if(editable(t,r,c)){total++;const v=rawCell(t,addr(r,c));if(String(v??'').trim()!=='')filled++}});return{total,filled,pct:total?filled/total*100:0}}
let currentTable=1;
function renderTables(){const t=TABLES.find(x=>x.id===currentTable)||TABLES[0];currentTable=t.id;$('#tableSelect').value=String(t.id);const comp=evalTables(t);let h='<table class="data-grid"><tbody>';for(let r=t.renderStart;r<t.rows;r++){h+='<tr>';for(let c=0;c<t.cols;c++){const a=addr(r,c),v=t.formulas[a]?comp[a]:rawCell(t,a);if(editable(t,r,c))h+=`<td class="input"><input data-cell="${a}" value="${esc(v)}"></td>`;else h+=`<td class="${t.formulas[a]?'formula':rowType(t,r)}" title="${a}${t.formulas[a]?' '+esc(t.formulas[a]):''}">${esc(v)}</td>`}h+='</tr>'}h+='</tbody></table>';const linked=MATRIX.filter(m=>(m.relatedTables||[]).includes(t.id));$('#tableViewer').innerHTML=`<div class="table-card"><div class="table-title"><div><p class="kicker">Tabel ${t.id}/43</p><h3>${esc(t.title)}</h3><div class="linked">Terkait indikator: ${linked.length?linked.map(m=>m.no).join(', '):'tidak dipetakan langsung'}</div></div><span class="tag good">${Object.keys(t.formulas).length} formula</span></div><div class="table-wrap">${h}</div><div class="formula-strip">${Object.entries(t.formulas).slice(0,20).map(([a,f])=>`<span class="formula-chip">${a}=${fmt(comp[a])}</span>`).join('')}</div></div>`;$$('[data-cell]').forEach(el=>{el.oninput=()=>{tableOv(t.id)[el.dataset.cell]=el.value;save();updateTableProgress()};el.onchange=renderTables});updateTableProgress()}
function updateTableProgress(){const s=tableCompletion();$('#tableProgress').textContent=`${s.pct.toFixed(0)}% terisi`}
function renderTableNav(){const s=$('#tableSelect');s.innerHTML=TABLES.map(t=>`<option value="${t.id}">${esc(t.title)}</option>`).join('');$('#tableIndex').innerHTML=TABLES.map(t=>`<button data-tid="${t.id}">${esc(t.title)}</button>`).join('');s.onchange=()=>{currentTable=Number(s.value);renderTables()};$('#prevTable').onclick=()=>{currentTable=currentTable<=1?43:currentTable-1;renderTables()};$('#nextTable').onclick=()=>{currentTable=currentTable>=43?1:currentTable+1;renderTables()};$$('[data-tid]').forEach(b=>b.onclick=()=>{currentTable=Number(b.dataset.tid);renderTables();window.scrollTo({top:$('#view-tables').offsetTop-70,behavior:'smooth'})});$('#exportCsv').onclick=exportCurrentCSV}
function exportCurrentCSV(){const t=TABLES.find(x=>x.id===currentTable),comp=evalTables(t),lines=[];for(let r=t.renderStart;r<t.rows;r++){const row=[];for(let c=0;c<t.cols;c++){const a=addr(r,c),v=t.formulas[a]?comp[a]:rawCell(t,a);row.push('"'+String(v??'').replace(/"/g,'""')+'"')}lines.push(row.join(','))}download(new Blob(['\ufeff'+lines.join('\n')],{type:'text/csv;charset=utf-8'}),`Tabel_${t.id}_FED_Sarjana.csv`)}
function renderEvidence(){const list=MATRIX.map(m=>({m,x:state.criteria[m.no]}));$('#evidenceList').innerHTML=list.map(z=>`<div class="evidence-row"><div class="crit-num">${z.m.no}</div><div><b>${esc(z.m.indicator)}</b><small class="muted">${esc(z.m.standard)}</small></div><input data-evtext="${z.m.no}" value="${esc(z.x.evidence)}" placeholder="Lokasi/tautan bukti"><select data-evstatus="${z.m.no}">${Object.keys(EVIDENCE_POINTS).map(v=>`<option ${z.x.evidenceStatus===v?'selected':''}>${v}</option>`).join('')}</select><input data-evowner="${z.m.no}" value="${esc(z.x.evidenceOwner)}" placeholder="Pemilik"></div>`).join('');$$('[data-evtext]').forEach(e=>e.oninput=()=>{state.criteria[e.dataset.evtext].evidence=e.value;save()});$$('[data-evstatus]').forEach(e=>e.onchange=()=>{state.criteria[e.dataset.evstatus].evidenceStatus=e.value;save();renderHero();renderDashboard()});$$('[data-evowner]').forEach(e=>e.oninput=()=>{state.criteria[e.dataset.evowner].evidenceOwner=e.value;save()})}
function renderIdentity(){const make=(arr,obj)=>arr.map(([k,l])=>`<label class="field">${l}<input data-idkey="${k}" value="${esc(obj[k]||'')}"></label>`).join('');$('#identityFields').innerHTML=make(ID_FIELDS,state.identity);$('#teamFields').innerHTML=make(TEAM_FIELDS,state.team);$$('[data-idkey]').forEach(e=>e.oninput=()=>{const key=e.dataset.idkey;if(ID_FIELDS.some(x=>x[0]===key))state.identity[key]=e.value;else state.team[key]=e.value;save()});$$('[data-front]').forEach(e=>{e.value=state.front[e.dataset.front]||'';e.oninput=()=>{state.front[e.dataset.front]=e.value;save()}})}
function renderMethodology(){const sy=META.syaratUnggulItems.join(', '),floor=META.scoreFloorOneItems.join(', ');$('#methodology').innerHTML=`<div class="panel"><p class="kicker">Akuntabilitas metode</p><h2>Metodologi Perhitungan dan Batas Interpretasi</h2><p>Aplikasi dibangun dari tiga berkas acuan yang disediakan: matriks penilaian Unggul Sarjana, formulir FED Unggul Sarjana, dan alat bantu penghitungan 43 tabel. Angka pada matriks diperlakukan sebagai sumber primer untuk skor butir dan bobot.</p><div class="method-grid"><div class="formula-card"><h3>1. Skor rubrik</h3><code>Kontribusi butir = skor butir × bobot</code><code>Indeks kesiapan internal = Σ(skor × bobot) / 282 × 100</code><p>Jumlah bobot = 141; skor maksimum setiap butir = 2; maksimum berbobot = 282. Indeks ini merupakan normalisasi internal, bukan ambang keputusan akreditasi resmi.</p></div><div class="formula-card"><h3>2. Mutu bukti</h3><code>Belum ada=0; Draft=0,33; Tersedia=0,67; Terverifikasi=1</code><code>Kematangan bukti = Σ(status bukti × bobot) / Σbobot × 100</code><p>Nilai bukti sengaja dipisahkan dari skor rubrik agar tidak mengubah deskriptor penilaian resmi.</p></div><div class="formula-card"><h3>3. Syarat perlu Unggul</h3><p>Butir yang pada kolom keterangan secara eksplisit memuat “SYARAT PERLU UNGGUL”: <b>${sy}</b>. Aplikasi menandai target skor 2 pada butir tersebut sebagai pemeriksaan kesiapan internal.</p><p>Butir dengan “tidak ada nilai kurang dari 1” (${floor}) hanya diperlakukan sebagai <b>batas skor rubrik</b>, bukan otomatis sebagai syarat perlu Unggul.</p></div><div class="formula-card"><h3>4. Prioritas tindakan</h3><p><b>Kritis</b>: syarat perlu Unggul belum skor 2 atau butir syarat minimum terakreditasi skor 0. <b>Tinggi</b>: skor 0 atau gap berbobot besar. <b>Sedang</b>: skor 1. <b>Rendah</b>: skor 2 tetapi bukti belum terverifikasi.</p></div></div></div><div class="panel"><h3>Catatan validasi sumber yang perlu ditelaah manusia</h3><ul class="warning-list"><li>Butir 15: rumus PJ pada keterangan sumber tertulis “NL/NJ × 100%”, yang secara matematis berlawanan dengan definisi persentase responden. Karena itu kalkulator meminta PJ (%) secara langsung dan tidak membalik rumus tanpa verifikasi resmi.</li><li>Butir 56: deskriptor skor 1 tertulis “25% ≥ Dosen&lt;50%”, sehingga nilai di bawah 25% tidak dipetakan otomatis.</li><li>Butir 64: deskriptor skor 1 menyebut “DPD” sementara indikator menggunakan “DPkMD”; aplikasi mengikuti variabel indikator dan menampilkan peringatan.</li><li>Beberapa butir menyatakan “tidak ada nilai kurang dari 1” walaupun kondisi data tertentu tidak dijelaskan; aplikasi tidak memaksakan interpretasi ketika kondisi berada di luar deskriptor eksplisit.</li></ul></div><div class="panel"><h3>Batas penggunaan</h3><p>Screening dokumen memakai kecocokan teks untuk membantu menemukan bukti, bukan untuk menilai kebenaran substantif. Keputusan skor harus dikonfirmasi evaluator internal terhadap dokumen asli, data tabel, bukti sahih, konsistensi tahun data, serta ketentuan LAMSPAK yang berlaku pada saat pengajuan.</p></div>`}
function reportDetails(){return MATRIX.map(m=>{const x=state.criteria[m.no],r=measurementResult(m,x);return`<div class="detail-item"><h4>${m.no}. ${esc(m.indicator)}</h4><div class="detail-grid"><b>Standar</b><span>${esc(m.standard)}</span><b>Skor / Bobot</b><span>${x.score??'-'} / ${m.weight} (kontribusi ${x.score===null?'-':fmt(Number(x.score)*m.weight)})</span><b>Status khusus</b><span>${m.syaratUnggul?'SYARAT PERLU UNGGUL; ':''}${m.syaratAkreditasi?'syarat minimum terakreditasi; ':''}${m.scoreFloor===1?'skor minimum rubrik 1':''}</span><b>Hasil pengukuran</b><span>${r?esc(r.summary)+(r.warning?' — '+esc(r.warning):''):'Tidak menggunakan kalkulator terstruktur atau data belum lengkap.'}</span><b>Narasi hasil</b><span>${esc(narrativeFor(m,x))}</span><b>Narasi FED</b><span>${esc(x.narrative||'Belum diisi')}</span><b>Bukti</b><span>${esc(x.evidence||'Belum dicatat')} [${esc(x.evidenceStatus)}]</span><b>Rekomendasi</b><span>${esc(recommendationFor(m,x))}</span><b>Rencana</b><span>${esc(x.plan.recommendation||'-')} | PIC: ${esc(x.plan.pic||'-')} | Tenggat: ${esc(x.plan.dueDate||'-')} | Target: ${esc(x.plan.target||'-')} | Status: ${esc(x.plan.status||'-')}</span><b>Catatan auditor</b><span>${esc(x.assessorNote||'-')}</span></div></div>`}).join('')}
function renderReport(){const s=scoreStats();const sy=MATRIX.filter(m=>m.syaratUnggul);$('#reportContent').innerHTML=`<div class="report-section"><h2>${esc(state.identity.programStudi||'Program Studi Sarjana')}</h2><p>${esc(state.identity.perguruanTinggi||'Perguruan Tinggi belum diisi')} • Tahun evaluasi ${esc(state.identity.tahunEvaluasi||'-')}</p><div class="kpis"><div class="kpi"><b>${s.index.toFixed(2)}</b><span>Indeks kesiapan internal</span></div><div class="kpi"><b>${fmt(s.weighted)}/${META.weightedMax}</b><span>Skor berbobot</span></div><div class="kpi"><b>${s.set}/73</b><span>Indikator dinilai</span></div><div class="kpi"><b>${s.evidencePct.toFixed(0)}%</b><span>Kematangan bukti</span></div><div class="kpi"><b>${s.unggulMet}/${s.unggulTotal}</b><span>Syarat perlu Unggul skor 2</span></div></div><p><b>Interpretasi:</b> ${esc($('#heroStatus')?.textContent||'')} — ${esc($('#heroNote')?.textContent||'')}</p><p>${esc(state.front.ringkasan||'Ringkasan eksekutif belum diisi.')}</p></div><div class="report-section"><h3>Syarat Perlu Unggul yang eksplisit pada matriks</h3><table class="report-table"><thead><tr><th>No</th><th>Indikator</th><th>Skor</th><th>Rubrik skor 2</th><th>Bukti</th></tr></thead><tbody>${sy.map(m=>{const x=state.criteria[m.no];return`<tr><td>${m.no}</td><td>${esc(m.indicator)}</td><td>${x.score??'-'}</td><td>${esc(m.score2)}</td><td>${esc(x.evidenceStatus)} - ${esc(x.evidence||'-')}</td></tr>`}).join('')}</tbody></table></div><div class="report-section"><h3>Rekap per Standar</h3><table class="report-table"><thead><tr><th>Standar</th><th>Skor berbobot</th><th>Maks.</th><th>Indeks</th><th>Dinilai</th><th>Kematangan bukti</th></tr></thead><tbody>${Object.entries(s.standards).map(([k,v])=>`<tr><td>${esc(k)}</td><td>${fmt(v.weighted)}</td><td>${v.max}</td><td>${(v.max?v.weighted/v.max*100:0).toFixed(2)}</td><td>${v.set}/${v.count}</td><td>${(v.evidenceMax?v.evidence/v.evidenceMax*100:0).toFixed(0)}%</td></tr>`).join('')}</tbody></table></div><div class="report-section"><h3>Rincian 73 Indikator</h3>${reportDetails()}</div><div class="report-section"><h3>Batasan</h3><p>Laporan ini merupakan instrumen evaluasi diri internal. Skor dan indeks kesiapan bukan keputusan akreditasi resmi. Semua butir harus diverifikasi terhadap instrumen LAMSPAK yang berlaku, dokumen sahih, konsistensi data, dan hasil asesmen.</p></div>`}
function renderAll(full=true){renderHero();renderDashboard();if(full){renderAssessment();renderPlans();renderTables();renderEvidence();renderIdentity();renderMethodology();renderReport()}else{renderAssessment();renderPlans();renderEvidence();renderReport()}}
function switchView(v){$$('.view').forEach(x=>x.classList.toggle('active',x.id==='view-'+v));$$('.sidebar [data-view]').forEach(x=>x.classList.toggle('active',x.dataset.view===v));if(v==='dashboard')renderDashboard();if(v==='assessment')renderAssessment();if(v==='plans')renderPlans();if(v==='tables')renderTables();if(v==='evidence')renderEvidence();if(v==='identity')renderIdentity();if(v==='method')renderMethodology();if(v==='report')renderReport();if(v==='analysis'&&window.renderAnalysis)window.renderAnalysis();window.scrollTo({top:0,behavior:'smooth'})}
function backup(){download(new Blob([JSON.stringify({app:'Muhasabbah FED LAMSPAK S1',version:3,exportedAt:new Date().toISOString(),state},null,2)],{type:'application/json'}),`backup_muhasabbah_lamspak_s1_${todayISO()}.json`)}
async function restore(file){try{const j=JSON.parse(await file.text()),s=j.state||j;if(!s.criteria)throw new Error('Format tidak dikenali');state={...fresh(),...s,criteria:{...fresh().criteria,...s.criteria}};MATRIX.forEach(m=>state.criteria[m.no]={...freshCriterion(),...(state.criteria[m.no]||{}),plan:{...freshCriterion().plan,...(state.criteria[m.no]?.plan||{})},metrics:{...(state.criteria[m.no]?.metrics||{})}});save();renderAll();toast('Data berhasil diimpor')}catch(e){alert('Gagal impor: '+e.message)}}
function exportPDF(){
  renderReport();
  const J=window.jspdf?.jsPDF;
  if(!J){switchView('report');setTimeout(()=>window.print(),200);return}
  const doc=new J({orientation:'landscape',unit:'mm',format:'a4'}),s=scoreStats();
  doc.setFontSize(15);doc.text('Laporan Evaluasi Diri Internal - LAMSPAK Sarjana',12,12);
  doc.setFontSize(8);doc.text(`${state.identity.programStudi||'Program Studi'} | ${state.identity.perguruanTinggi||'Perguruan Tinggi'}`,12,18);
  doc.text(`Indeks kesiapan ${s.index.toFixed(2)}/100 | Skor ${fmt(s.weighted)}/${META.weightedMax} | Indikator dinilai ${s.set}/73 | Kematangan bukti ${s.evidencePct.toFixed(0)}% | Syarat perlu Unggul ${s.unggulMet}/${s.unggulTotal}`,12,22);
  doc.setFontSize(7);doc.text('Catatan: indeks internal, bukan keputusan akreditasi resmi. Verifikasi setiap skor terhadap instrumen dan bukti sahih.',12,26);
  if(typeof doc.autoTable==='function'){
    doc.autoTable({
      startY:30,
      head:[['No','Indikator','Skor / Bobot','Bukti','Narasi hasil penilaian','Rekomendasi dan rencana']],
      body:MATRIX.map(m=>{
        const x=state.criteria[m.no],r=measurementResult(m,x),special=[m.syaratUnggul?'SYARAT PERLU UNGGUL':'',m.syaratAkreditasi?'syarat minimum terakreditasi':'',m.scoreFloor===1?'skor minimum rubrik 1':''].filter(Boolean).join('; ');
        const narrative=[narrativeFor(m,x),x.narrative?`Narasi FED: ${x.narrative}`:'',r?.warning?`Catatan pengukuran: ${r.warning}`:''].filter(Boolean).join('\n');
        const plan=[recommendationFor(m,x),x.plan.recommendation?`Tindakan: ${x.plan.recommendation}`:'',x.plan.pic?`PIC: ${x.plan.pic}`:'',x.plan.dueDate?`Tenggat: ${x.plan.dueDate}`:'',x.plan.target?`Target: ${x.plan.target}`:'',x.plan.status?`Status: ${x.plan.status}`:''].filter(Boolean).join('\n');
        const evidence=`${x.evidenceStatus}${x.evidence?' — '+x.evidence:''}${x.evidenceOwner?' | Pemilik: '+x.evidenceOwner:''}${x.verifiedDate?' | Verifikasi: '+x.verifiedDate:''}`;
        return [m.no,`${m.indicator}\n${m.standard.replace(/^\d+\.\s*/,'')}${special?'\n['+special+']':''}`,`${x.score??'-'} / ${m.weight}\nKontribusi: ${x.score===null?'-':fmt(Number(x.score)*m.weight)}`,evidence,narrative,plan];
      }),
      styles:{fontSize:5.1,cellPadding:1.1,overflow:'linebreak',valign:'top'},
      headStyles:{fillColor:[15,76,92]},
      columnStyles:{0:{cellWidth:8},1:{cellWidth:58},2:{cellWidth:19},3:{cellWidth:40},4:{cellWidth:83},5:{cellWidth:83}},
      margin:{left:4,right:4,top:8,bottom:8}
    });
  }
  doc.save(`Laporan_Muhasabbah_LAMSPAK_S1_${todayISO()}.pdf`)
}
async function exportWord(){
  if(!window.docx){
    renderReport();
    const body=$('#reportContent').innerHTML;
    const html=`<!doctype html><html><head><meta charset="utf-8"><title>Laporan Muhasabbah LAMSPAK</title><style>body{font-family:Arial,sans-serif;font-size:10pt;line-height:1.35}table{border-collapse:collapse;width:100%;margin:8px 0 14px}th,td{border:1px solid #777;padding:4px;vertical-align:top}h2,h3,h4{page-break-after:avoid}.detail-item{page-break-inside:avoid;margin-bottom:12px}.detail-grid{display:block}.detail-grid b{display:block;margin-top:4px}.kpis{display:block}.kpi{display:inline-block;border:1px solid #aaa;padding:6px;margin:2px}</style></head><body>${body}</body></html>`;
    download(new Blob(['\ufeff'+html],{type:'application/msword'}),`Laporan_Muhasabbah_LAMSPAK_S1_${todayISO()}.doc`);
    toast('Pustaka DOCX tidak termuat; laporan diekspor sebagai Word .doc.');
    return
  }
  const {Document,Packer,Paragraph,TextRun,Table,TableRow,TableCell,HeadingLevel,WidthType,PageOrientation}=window.docx,s=scoreStats();
  const p=t=>new Paragraph({children:[new TextRun(String(t??''))]});
  const cell=t=>new TableCell({children:[p(t)]});
  const row=(a,b)=>new TableRow({children:[cell(a),cell(b)]});
  const children=[
    new Paragraph({text:'Laporan Evaluasi Diri Internal - LAMSPAK Sarjana',heading:HeadingLevel.TITLE}),
    p(`Program Studi: ${state.identity.programStudi||'-'}`),p(`Perguruan Tinggi: ${state.identity.perguruanTinggi||'-'}`),p(`Tahun evaluasi: ${state.identity.tahunEvaluasi||'-'}`),
    p(`Indeks kesiapan internal: ${s.index.toFixed(2)}/100`),p(`Skor berbobot: ${fmt(s.weighted)}/${META.weightedMax}`),p(`Indikator dinilai: ${s.set}/73`),p(`Kematangan bukti berbobot: ${s.evidencePct.toFixed(0)}%`),p(`Syarat perlu Unggul skor 2: ${s.unggulMet}/${s.unggulTotal}`),
    p('Catatan: laporan ini merupakan alat evaluasi diri internal dan bukan keputusan akreditasi resmi.'),
    new Paragraph({text:'Rekap per Standar',heading:HeadingLevel.HEADING_1})
  ];
  const sr=[new TableRow({children:['Standar','Skor berbobot','Maksimum','Indeks','Dinilai','Kematangan bukti'].map(cell)})];
  Object.entries(s.standards).forEach(([k,v])=>sr.push(new TableRow({children:[k,fmt(v.weighted),v.max,(v.max?v.weighted/v.max*100:0).toFixed(2)+'%',`${v.set}/${v.count}`,(v.evidenceMax?v.evidence/v.evidenceMax*100:0).toFixed(0)+'%'].map(cell)})));
  children.push(new Table({width:{size:100,type:WidthType.PERCENTAGE},rows:sr}),new Paragraph({text:'Rincian 73 Indikator',heading:HeadingLevel.HEADING_1}));
  MATRIX.forEach(m=>{
    const x=state.criteria[m.no],r=measurementResult(m,x),special=[m.syaratUnggul?'SYARAT PERLU UNGGUL':'',m.syaratAkreditasi?'syarat minimum terakreditasi':'',m.scoreFloor===1?'skor minimum rubrik 1':''].filter(Boolean).join('; ')||'-';
    const rt=[
      row('Standar',m.standard),row('Skor / bobot',`${x.score??'-'} / ${m.weight} | kontribusi ${x.score===null?'-':fmt(Number(x.score)*m.weight)} dari maksimum ${2*m.weight}`),row('Status khusus',special),
      row('Hasil pengukuran',r?`${r.summary}${r.warning?' — '+r.warning:''}`:'Tidak menggunakan kalkulator terstruktur atau data belum lengkap.'),
      row('Rubrik skor 2',m.score2),row('Rubrik skor 1',m.score1),row('Rubrik skor 0',m.score0),
      row('Narasi hasil penilaian',narrativeFor(m,x)),row('Narasi FED',x.narrative||'Belum diisi'),
      row('Bukti',`${x.evidence||'Belum dicatat'} | Status: ${x.evidenceStatus} | Pemilik: ${x.evidenceOwner||'-'} | Verifikasi: ${x.verifiedDate||'-'}`),
      row('Rekomendasi',recommendationFor(m,x)),row('Rencana tindak lanjut',`${x.plan.recommendation||'-'} | PIC: ${x.plan.pic||'-'} | Tenggat: ${x.plan.dueDate||'-'} | Target: ${x.plan.target||'-'} | Status: ${x.plan.status||'-'}`),
      row('Catatan auditor internal',x.assessorNote||'-')
    ];
    children.push(new Paragraph({text:`${m.no}. ${m.indicator}`,heading:HeadingLevel.HEADING_2}),new Table({width:{size:100,type:WidthType.PERCENTAGE},rows:rt}));
  });
  const doc=new Document({sections:[{properties:{page:{size:{orientation:PageOrientation?.LANDSCAPE||'landscape'}}},children}]});
  const blob=await Packer.toBlob(doc);download(blob,`Laporan_Muhasabbah_LAMSPAK_S1_${todayISO()}.docx`)
}
$$('.sidebar [data-view]').forEach(b=>b.onclick=()=>switchView(b.dataset.view));$('#critSearch').oninput=renderAssessment;$('#critFilter').onchange=renderAssessment;$('#btnBackup').onclick=backup;$('#btnRestore').onclick=()=>$('#restoreInput').click();$('#restoreInput').onchange=e=>{if(e.target.files[0])restore(e.target.files[0]);e.target.value=''};$('#btnPdf').onclick=exportPDF;$('#btnWord').onclick=exportWord;$('#btnPrint').onclick=()=>{renderReport();setTimeout(()=>window.print(),150)};$('#btnReset').onclick=()=>{if(confirm('Hapus seluruh data evaluasi yang tersimpan di perangkat ini?')){state=fresh();localStorage.removeItem(STORAGE_KEY);renderAll();toast('Data direset')}};$('#btnAnalyze').onclick=()=>{switchView('analysis');$('#fedInput').click()};
renderTableNav();renderAll();
